insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('pri-math-016', '"b"'::jsonb, 'Adding 1,000 changes only the thousands digit: 3 thousands become 4 thousands, so 3,456 becomes 4,456.', '{"a":"3,556 is 100 more (the hundreds digit changed).","c":"3,466 is 10 more (the tens digit changed).","d":"13,456 is 10,000 more."}'::jsonb, null),
  ('pri-math-017', '{"value":42,"tolerance":0}'::jsonb, '6 × 7 = 42. Check: 6 × 5 = 30, plus 6 × 2 = 12, and 30 + 12 = 42.', null, '[{"value":48,"why":"48 is 6 × 8, one group of 6 too many."},{"value":36,"why":"36 is 6 × 6, one group of 6 too few."}]'::jsonb),
  ('pri-math-018', '{"value":12,"tolerance":0}'::jsonb, '12 × 12 = 144, so 144 ÷ 12 = 12.', null, '[{"value":132,"why":"132 is 144 − 12; division asks how many 12s fit into 144."}]'::jsonb),
  ('pri-math-019', '["a","c","e"]'::jsonb, '12 = 4 × 3, 20 = 4 × 5 and 36 = 4 × 9, so they are multiples of 4.', '{"b":"18 ÷ 4 = 4 remainder 2, so 18 is not a multiple of 4.","d":"30 ÷ 4 = 7 remainder 2, so 30 is not a multiple of 4."}'::jsonb, null),
  ('pri-math-020', '["b","c","a"]'::jsonb, 'With the same top number, more equal pieces means smaller pieces: 1/8 < 1/4 < 1/2.', null, null),
  ('pri-math-021', '{"a":"z","b":"x","c":"y"}'::jsonb, 'Triangle: 3 sides. Pentagon: 5 ("penta" means five). Octagon: 8 ("octo" means eight, like an octopus''s arms).', null, null),
  ('pri-math-022', '"b"'::jsonb, '3/5 = 6/10 = 60/100 = 60%.', '{"a":"35% just joins the digits 3 and 5; 3/5 means 3 out of 5 equal parts.","c":"53% swaps the digits; 3 out of 5 is more than half, i.e. 60%.","d":"30% is 3/10, not 3/5."}'::jsonb, null),
  ('pri-math-023', '{"value":19,"tolerance":0}'::jsonb, 'Empty seats = total − taken = 48 − 29 = 19.', null, '[{"value":77,"why":"77 adds the numbers; we need what is left after the taken seats, so subtract."},{"value":21,"why":"Check the borrowing: 48 − 29 = 19 (48 − 30 = 18, then add 1 back)."}]'::jsonb),
  ('pri-math-024', '"c"'::jsonb, 'A prime number has exactly two factors: 1 and itself. 29 cannot be divided evenly by any other whole number.', '{"a":"21 = 3 × 7, so it has more than two factors.","b":"27 = 3 × 9, so it is not prime.","d":"33 = 3 × 11, so it is not prime."}'::jsonb, null),
  ('pri-math-025', '{"value":2500,"tolerance":0,"unit":"ml"}'::jsonb, '1 litre = 1,000 ml, so 2.5 litres = 2.5 × 1,000 = 2,500 ml.', null, '[{"value":250,"why":"There are 1,000 ml in a litre, not 100."}]'::jsonb),
  ('pri-math-026', '"true"'::jsonb, 'Write both with two decimal places: 0.70 and 0.65. Seventy hundredths is more than sixty-five hundredths.', '{"false":"Having more digits does not make a decimal bigger. Compare place by place: 7 tenths beats 6 tenths."}'::jsonb, null),
  ('pri-math-027', '{"value":19,"tolerance":0}'::jsonb, 'Each number is 4 more than the one before, so 15 + 4 = 19.', null, '[{"value":18,"why":"The pattern adds 4 each time, not 3."}]'::jsonb),
  ('pri-math-028', '"b"'::jsonb, 'A right angle is a quarter turn: 90°. The corner of a book is a right angle.', '{"a":"45° is half a right angle.","c":"180° is a straight line (a half turn).","d":"360° is a full turn."}'::jsonb, null),
  ('pri-math-029', '{"value":49,"tolerance":0,"unit":"cm²"}'::jsonb, 'Area of a square = side × side = 7 × 7 = 49 cm².', null, '[{"value":28,"why":"28 cm is the perimeter (4 × 7), not the area."},{"value":14,"why":"14 is 7 + 7; area multiplies the two sides."}]'::jsonb),
  ('pri-math-030', '["b","c","a"]'::jsonb, 'a.m. times are before noon and p.m. times are after noon: 9:40 a.m., then 11:05 a.m., then 1:15 p.m.', null, null),
  ('pri-math-031', '"a"'::jsonb, 'Look at the tenths digit: 4 is less than 5, so round down to 6.', '{"b":"6.5 is rounded to one decimal place, not to a whole number.","c":"Only round up when the tenths digit is 5 or more; here it is 4.","d":"6.4 keeps a decimal place; a whole number has none."}'::jsonb, null),
  ('pri-math-032', '{"value":7.5,"tolerance":0.001,"unit":"RM"}'::jsonb, '3 × RM2.50 = RM7.50. (RM2.50 + RM2.50 = RM5.00, plus RM2.50 = RM7.50.)', null, '[{"value":5.5,"why":"That adds 3 to the price; he buys 3 notebooks, so multiply by 3."}]'::jsonb),
  ('pri-math-033', '{"accept":["equilateral","equilateral triangle"]}'::jsonb, 'An equilateral triangle has three equal sides (and three equal 60° angles). "Equi" means equal and "lateral" means side.', null, null),
  ('pri-math-034', '["a","c","d"]'::jsonb, 'Squares, rectangles and rhombuses are all quadrilaterals: shapes with four straight sides.', '{"b":"A triangle has three sides.","e":"A pentagon has five sides."}'::jsonb, null),
  ('pri-math-035', '{"value":15,"tolerance":0}'::jsonb, 'One quarter means dividing into 4 equal parts: 60 ÷ 4 = 15.', null, '[{"value":240,"why":"240 is 60 × 4; finding a quarter means dividing by 4."},{"value":30,"why":"30 is one half of 60, not one quarter."}]'::jsonb),
  ('pri-sci-011', '"a"'::jsonb, 'Roots grow into the soil, hold the plant in place and absorb water and minerals.', '{"b":"Leaves make food using sunlight; they lose water rather than take it from the soil.","c":"Flowers help the plant reproduce.","d":"Fruit protects seeds and helps spread them."}'::jsonb, null),
  ('pri-sci-012', '["a","c","e"]'::jsonb, 'Living things grow, need food and water, respond to their surroundings and reproduce. Mushrooms (fungi), ferns (plants) and beetles (animals) all do.', '{"b":"A rock does not grow, feed or reproduce.","d":"Living things need water, but water itself is not alive."}'::jsonb, null),
  ('pri-sci-013', '"false"'::jsonb, 'The Moon shines because it reflects light from the Sun. That is why we see different phases as different parts are lit.', '{"true":"The Moon has no light of its own; moonlight is sunlight bouncing off its surface."}'::jsonb, null),
  ('pri-sci-014', '"b"'::jsonb, 'Our cells use oxygen and produce carbon dioxide as waste, so the air we breathe out has more carbon dioxide.', '{"a":"We breathe out less oxygen than we breathe in, because our body uses some.","c":"Nitrogen passes in and out almost unchanged.","d":"There is hardly any helium in air, and our body does not make it."}'::jsonb, null),
  ('pri-sci-015', '["b","d","a","c"]'::jsonb, 'Egg → caterpillar → pupa → adult. This big change in body shape is called complete metamorphosis.', null, null),
  ('pri-sci-016', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Frogs are amphibians (they start life in water), eagles are birds (feathers, beaks) and snakes are reptiles (dry, scaly skin).', null, null),
  ('pri-sci-017', '{"accept":["gravity","gravitational force","force of gravity"]}'::jsonb, 'Gravity pulls everything towards the Earth''s centre. It is why a dropped ball falls down.', null, null),
  ('pri-sci-018', '"a"'::jsonb, 'A light source makes its own light. The Sun gives off light; the others only reflect or let light through.', '{"b":"A mirror reflects light but does not make it.","c":"The Moon reflects sunlight; it is not a light source.","d":"A window lets light pass through; it does not make light."}'::jsonb, null),
  ('pri-sci-019', '"a"'::jsonb, 'Herbivores (like cows and rabbits) eat only plants.', '{"b":"Carnivores eat other animals.","c":"Omnivores eat both plants and animals.","d":"Predators hunt other animals for food."}'::jsonb, null),
  ('pri-sci-020', '"true"'::jsonb, 'Heat moves through metals quickly. That is why a metal spoon in hot soup soon feels hot, while a wooden spoon does not.', '{"false":"Metals let heat pass through easily; materials like wood and plastic are the poor conductors (insulators)."}'::jsonb, null),
  ('pri-sci-021', '"a"'::jsonb, 'The lungs take oxygen from the air into the blood and remove carbon dioxide.', '{"b":"Kidneys clean the blood and make urine.","c":"The liver processes nutrients and removes harmful substances.","d":"The stomach helps digest food."}'::jsonb, null),
  ('pri-sci-022', '{"accept":["condensation"]}'::jsonb, 'Condensation is gas turning into liquid when it cools, like droplets forming on a cold glass. It is how clouds form in the water cycle.', null, null),
  ('pri-sci-023', '"d"'::jsonb, 'One orbit of the Sun takes about 365¼ days: one year.', '{"a":"One day is how long the Earth takes to spin once on its own axis.","b":"A week has no link to the Earth''s orbit.","c":"About a month is how long the Moon takes to orbit the Earth."}'::jsonb, null),
  ('pri-sci-024', '["a","c"]'::jsonb, 'Magnets attract iron and materials containing iron, such as steel.', '{"b":"Plastic is not magnetic.","d":"Wood is not magnetic.","e":"Aluminium is a metal, but it is not attracted to magnets. Not all metals are magnetic."}'::jsonb, null),
  ('pri-sci-025', '"a"'::jsonb, 'Lightning and thunder happen together, but light reaches us almost instantly while sound travels about 343 metres per second, so the thunder arrives later.', '{"b":"It is the other way round: light is about a million times faster than sound.","c":"Thunder is the sound of the lightning itself; both happen at the same moment.","d":"The tiny difference in where our eyes and ears are cannot cause a delay of seconds."}'::jsonb, null),
  ('pri-eng-006', '"b"'::jsonb, 'We use "an" before words that begin with a vowel sound: an elephant, an apple.', '{"a":"\"A\" goes before consonant sounds (a dog); \"elephant\" starts with a vowel sound.","c":"\"Much\" is used with things we cannot count, like water.","d":"\"Few\" goes with plural nouns (few elephants)."}'::jsonb, null),
  ('pri-eng-007', '"b"'::jsonb, '"Eat" is irregular: eat → ate → eaten. Yesterday I ate rice.', '{"a":"\"Eated\" is not a word; \"eat\" does not use -ed.","c":"\"Eaten\" needs a helper: I have eaten.","d":"\"Eating\" shows an action in progress."}'::jsonb, null),
  ('pri-eng-008', '["a","c","e"]'::jsonb, 'Nouns name people, animals, places or things: dog (animal), ball (thing), park (place).', '{"b":"\"Chased\" is a verb: it is the action.","d":"\"In\" is a preposition: it tells us where."}'::jsonb, null),
  ('pri-eng-009', '["b","c","a"]'::jsonb, 'Look at the first letters: a comes before l, and l comes before m. So: apple, lemon, mango.', null, null),
  ('pri-eng-010', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Opposites (antonyms): hot – cold, tall – short, happy – sad.', null, null),
  ('pri-eng-011', '{"accept":["mice"]}'::jsonb, '"Mouse" has an irregular plural: one mouse, two mice.', null, null),
  ('pri-eng-012', '"a"'::jsonb, 'A question asks something and ends with a question mark.', '{"b":"This is a statement: it tells us something.","c":"This is a command: it tells someone to do something.","d":"This is an exclamation: it shows a strong feeling and ends with !"}'::jsonb, null),
  ('pri-eng-013', '"c"'::jsonb, 'A verb is an action or doing word. "Sing" is what the children do.', '{"a":"\"The\" is an article.","b":"\"Children\" is a noun: it names who.","d":"\"Loudly\" is an adverb: it tells how they sing."}'::jsonb, null),
  ('pri-eng-014', '{"accept":["stop"]}'::jsonb, 'A statement ends with a full stop (.). In American English it is called a period.', null, null),
  ('pri-eng-015', '"a"'::jsonb, 'Rhyming words end with the same sound: c-at, h-at.', '{"b":"\"Cut\" ends in -ut, not -at.","c":"\"Cot\" ends in -ot.","d":"\"Cap\" starts the same way but ends in -ap."}'::jsonb, null),
  ('pri-eng-016', '"true"'::jsonb, 'Adverbs describe how, when or where something happens. "Quickly" tells us how an action is done, and many adverbs end in -ly.', '{"false":"\"Quickly\" describes a verb (She ran quickly), which is exactly what an adverb does."}'::jsonb, null),
  ('pri-eng-017', '"b"'::jsonb, '"Because" is spelled b-e-c-a-u-s-e. A memory trick: Big Elephants Can Always Understand Small Elephants.', '{"a":"The letters a and u are swapped.","c":"There is no o in because.","d":"There is an extra a: it is be-cause, not bea-cause."}'::jsonb, null),
  ('pri-eng-018', '"a"'::jsonb, '"Enormous" means extremely large, like an enormous whale.', '{"b":"\"Very small\" is the opposite; that would be \"tiny\".","c":"\"Very fast\" would be \"speedy\" or \"rapid\".","d":"\"Very quiet\" would be \"silent\"."}'::jsonb, null),
  ('pri-eng-019', '"b"'::jsonb, 'When comparing two people with "than", short adjectives add -er: taller.', '{"a":"\"Tall\" does not compare; we need the -er form before \"than\".","c":"\"Tallest\" compares three or more: the tallest in the class.","d":"Short adjectives like \"tall\" use -er, not \"more\"."}'::jsonb, null),
  ('pri-eng-020', '{"accept":["don''t"]}'::jsonb, '"Do not" becomes "don''t": the apostrophe replaces the missing letter o.', null, null)
